```cpp
#include <iostream>
#include <string>
#include <pugixml.hpp>

std::string convertMarkdownToHtml(const std::string& markdown) {
    pugi::xml_document doc;
    pugi::xml_node root = doc.allocate_node(pugi::node_element, "div");

    // Parse the Markdown into a pugixml tree
    pugi::xml_parse_result result = doc.parse_memory(markdown.c_str(), markdown.size(), "markdown");
    if (!result) {
        std::cerr << "Error parsing Markdown: " << result.description() << std::endl;
        return "";  // Return empty string if parsing fails
    }

    // Convert the pugixml tree to HTML
    for (pugi::xml_node node = root.first_child(); node; node = node.next_sibling()) {
        switch (node.node_type()) {
            case pugi::node_element:
                root.append_child(pugi::node_element).append_child(pugi::node_cdata).set_value(node.child_value());
                break;
            case pugi::node_text:
                root.append_child(pugi::node_element).append_child(pugi::node_cdata).set_value(node.value());
                break;
            case pugi::node_pi:
            case pugi::node_comment:
            case pugi::node_declaration:
                break;  // Ignore non-element and non-text nodes
        }
    }

    // Serialize the HTML to a string
    std::stringstream html;
    doc.save(html);

    return html.str();
}

int main() {
    std::string markdown = "Hello **world**! This is *markdown* converted to **HTML**.";
    std::string html = convertMarkdownToHtml(markdown);
    std::cout << "Markdown:\n" << markdown << "\n\nHTML:\n" << html << std::endl;

    return 0;
}
```

